const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:64227/status';
const OUTPUT = path.join(__dirname, 'results', 'status.json');

fetch(ENDPOINT)
  .then((res) => res.json())
  .then((data) => {
    fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
    fs.writeFileSync(OUTPUT, JSON.stringify({ status: data.status }));
    console.log('wrote', OUTPUT, 'status=' + data.status);
  })
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });

